import java.util.ArrayList;
import java.util.Collection;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Set;

public interface ArrayValueProvider {
	ArrayValueProvider EMPTY = new ArrayValueProvider() {
		@Override
		public int getLength(Context cx) {
			return 0;
		}

		@Override
		public Object getArrayValue(Context cx, int index) {
			return null;
		}

		@Override
		public Object getErrorSource(Context cx) {
			return null;
		}
	};

	int getLength(Context cx);

	Object getArrayValue(Context cx, int index);

	Object getErrorSource(Context cx);

	default Object createArray(Context cx, TypeInfo target) {
		int len = getLength(cx);
		Object arr = target.newArray(len);

		for (int i = 0; i < len; i++) {
			try {
				Array.set(arr, i, cx.jsToJava(getArrayValue(cx, i), target));
			} catch (EvaluatorException ee) {
				return cx.reportConversionError(getErrorSource(cx), target);
			}
		}

		return arr;
	}

	default Object createList(Context cx, TypeInfo target) {
		int len = getLength(cx);

		if (len == 0) {
			return List.of();
		} else if (len == 1) {
			try {
				return List.of(cx.jsToJava(getArrayValue(cx, 0), target));
			} catch (EvaluatorException ee) {
				return cx.reportConversionError(getErrorSource(cx), target);
			}
		}

		List<Object> list = new ArrayList<Object>(len);

		for (int i = 0; i < len; i++) {
			try {
				list.add(cx.jsToJava(getArrayValue(cx, i), target));
			} catch (EvaluatorException ee) {
				return cx.reportConversionError(getErrorSource(cx), target);
			}
		}

		return list;
	}

	default Object createSet(Context cx, TypeInfo target) {
		int len = getLength(cx);

		if (len == 0) {
			return Set.of();
		} else if (len == 1) {
			try {
				return Set.of(cx.jsToJava(getArrayValue(cx, 0), target));
			} catch (EvaluatorException ee) {
				return cx.reportConversionError(getErrorSource(cx), target);
			}
		}

		Set<Object> set = new HashSet<Object>(len);

		for (int i = 0; i < len; i++) {
			try {
				set.add(cx.jsToJava(getArrayValue(cx, i), target));
			} catch (EvaluatorException ee) {
				return cx.reportConversionError(getErrorSource(cx), target);
			}
		}

		return set;
	}

	final class FromObject implements ArrayValueProvider {
		private final Object object;

		public FromObject(Object object) {
			this.object = object;
		}

		public Object object() {
			return object;
		}

		public static final FromObject FROM_NULL = new FromObject(null);

		@Override
		public int getLength(Context cx) {
			return 1;
		}

		@Override
		public Object getArrayValue(Context cx, int index) {
			return object;
		}

		@Override
		public Object getErrorSource(Context cx) {
			return object;
		}

		@Override
		public boolean equals(Object other) {
			if (!(other instanceof FromObject)) {
				return false;
			}
			FromObject that = (FromObject) other;
			return Objects.equals(object, that.object);
		}

		@Override
		public int hashCode() {
			int hash = 0;
			hash = 31 * hash + Objects.hashCode(object);
			return hash;
		}

		@Override
		public String toString() {
			return "FromObject[object=" + object + "]";
		}
	}

	static ArrayValueProvider fromNativeArray(NativeArray array) {
		return array.getLength() == 0 ? EMPTY : new FromNativeArray(array);
	}

	final class FromNativeArray implements ArrayValueProvider {
		private final NativeArray array;

		public FromNativeArray(NativeArray array) {
			this.array = array;
		}

		public NativeArray array() {
			return array;
		}

		@Override
		public int getLength(Context cx) {
			return (int) array.getLength();
		}

		@Override
		public Object getArrayValue(Context cx, int index) {
			return array.get(cx, index, array);
		}

		@Override
		public Object getErrorSource(Context cx) {
			return array;
		}

		@Override
		public boolean equals(Object other) {
			if (!(other instanceof FromNativeArray)) {
				return false;
			}
			FromNativeArray that = (FromNativeArray) other;
			return Objects.equals(array, that.array);
		}

		@Override
		public int hashCode() {
			int hash = 0;
			hash = 31 * hash + Objects.hashCode(array);
			return hash;
		}

		@Override
		public String toString() {
			return "FromNativeArray[array=" + array + "]";
		}
	}

	final class FromJavaArray implements ArrayValueProvider {
		private final Object array;

		private final int length;

		public FromJavaArray(Object array, int length) {
			this.array = array;
			this.length = length;
		}

		public Object array() {
			return array;
		}

		public int length() {
			return length;
		}

		@Override
		public int getLength(Context cx) {
			return length;
		}

		@Override
		public Object getArrayValue(Context cx, int index) {
			return Array.get(array, index);
		}

		@Override
		public Object getErrorSource(Context cx) {
			return array;
		}

		@Override
		public boolean equals(Object other) {
			if (!(other instanceof FromJavaArray)) {
				return false;
			}
			FromJavaArray that = (FromJavaArray) other;
			return Objects.equals(array, that.array) && length == that.length;
		}

		@Override
		public int hashCode() {
			int hash = 0;
			hash = 31 * hash + Objects.hashCode(array);
			hash = 31 * hash + Integer.hashCode(length);
			return hash;
		}

		@Override
		public String toString() {
			return "FromJavaArray[array=" + array + ", length=" + length + "]";
		}
	}

	final class FromPlainJavaArray implements ArrayValueProvider {
		private final Object[] array;

		public FromPlainJavaArray(Object[] array) {
			this.array = array;
		}

		public Object[] array() {
			return array;
		}

		@Override
		public int getLength(Context cx) {
			return array.length;
		}

		@Override
		public Object getArrayValue(Context cx, int index) {
			return array[index];
		}

		@Override
		public Object getErrorSource(Context cx) {
			return array;
		}

		@Override
		public boolean equals(Object other) {
			if (!(other instanceof FromPlainJavaArray)) {
				return false;
			}
			FromPlainJavaArray that = (FromPlainJavaArray) other;
			return Objects.equals(array, that.array);
		}

		@Override
		public int hashCode() {
			int hash = 0;
			hash = 31 * hash + Objects.hashCode(array);
			return hash;
		}

		@Override
		public String toString() {
			return "FromPlainJavaArray[array=" + array + "]";
		}
	}

	static ArrayValueProvider fromJavaList(List<?> list, Object errorSource) {
		return list.isEmpty() ? EMPTY : new FromJavaList(list, errorSource);
	}

	final class FromJavaList implements ArrayValueProvider {
		private final List<?> list;

		private final Object errorSource;

		public FromJavaList(List<?> list, Object errorSource) {
			this.list = list;
			this.errorSource = errorSource;
		}

		public List<?> list() {
			return list;
		}

		public Object errorSource() {
			return errorSource;
		}

		@Override
		public int getLength(Context cx) {
			return list.size();
		}

		@Override
		public Object getArrayValue(Context cx, int index) {
			return list.get(index);
		}

		@Override
		public Object getErrorSource(Context cx) {
			return errorSource;
		}

		@Override
		public boolean equals(Object other) {
			if (!(other instanceof FromJavaList)) {
				return false;
			}
			FromJavaList that = (FromJavaList) other;
			return Objects.equals(list, that.list) && Objects.equals(errorSource, that.errorSource);
		}

		@Override
		public int hashCode() {
			int hash = 0;
			hash = 31 * hash + Objects.hashCode(list);
			hash = 31 * hash + Objects.hashCode(errorSource);
			return hash;
		}

		@Override
		public String toString() {
			return "FromJavaList[list=" + list + ", errorSource=" + errorSource + "]";
		}
	}

	static ArrayValueProvider fromIterable(Iterable<?> iterable) {
		int len;

		if (iterable instanceof Collection<?>) {
			len = ((Collection<?>) iterable).size();
		} else {
			len = 0;

			for (Object ignored : iterable) {
				len++;
			}
		}

		return len == 0 ? EMPTY : new FromIterator(len, iterable.iterator(), iterable);
	}

	final class FromIterator implements ArrayValueProvider {
		private final int length;

		private final Iterator<?> iterator;

		private final Object errorSource;

		public FromIterator(int length, Iterator<?> iterator, Object errorSource) {
			this.length = length;
			this.iterator = iterator;
			this.errorSource = errorSource;
		}

		public int length() {
			return length;
		}

		public Iterator<?> iterator() {
			return iterator;
		}

		public Object errorSource() {
			return errorSource;
		}

		@Override
		public int getLength(Context cx) {
			return length;
		}

		@Override
		public Object getArrayValue(Context cx, int index) {
			return iterator.next();
		}

		@Override
		public Object getErrorSource(Context cx) {
			return errorSource;
		}

		@Override
		public boolean equals(Object other) {
			if (!(other instanceof FromIterator)) {
				return false;
			}
			FromIterator that = (FromIterator) other;
			return length == that.length && Objects.equals(iterator, that.iterator) && Objects.equals(errorSource, that.errorSource);
		}

		@Override
		public int hashCode() {
			int hash = 0;
			hash = 31 * hash + Integer.hashCode(length);
			hash = 31 * hash + Objects.hashCode(iterator);
			hash = 31 * hash + Objects.hashCode(errorSource);
			return hash;
		}

		@Override
		public String toString() {
			return "FromIterator[length=" + length + ", iterator=" + iterator + ", errorSource=" + errorSource + "]";
		}
	}
}

